('FUSION_I','{"label": "융합전공Ⅰ (프로그램당)", "basic": 3000, "required": 15000, "elective": 21000, "total": 39000, "freeElective": 21000, "programsRequired": 2, "majorTotal": 78000, "note": "트랙·학과·전공 중 2개 이상 교육과정을 각 39학점 이수"}'::jsonb),
('FUSION_II_MAIN','{"label": "융합전공Ⅱ 주전공", "basic": 3000, "required": 15000, "elective": 39000, "total": 57000, "freeElective": 21000, "pairedWith": "MINOR", "majorTotal": 78000, "note": "학과·전공 1개 57학점 + 타 교육과정 부전공 21학점, 다전공 신청기간(2월·8월)에 부전공 신청 필요"}'::jsonb),
('MINOR','{"label": "부전공", "basic": 3000, "required": 12000, "elective": 6000, "total": 21000, "note": "트랙·학과·전공 교육과정 21학점. 모든 이수과정에 1개 이상 추가 가능, 부전공 지정과목 확인 필요"}'::jsonb),
('DEEP_GENERAL','{"label": "심화전공(일반 학과·전공)", "basic": 3000, "required": 15000, "elective": 60000, "total": 78000, "freeElective": 21000, "note": "1·2트랙을 동일 학과·전공으로 선택"}'::jsonb),
('DEEP_CREATIVE','{"label": "심화전공(창의융합대학 소속 학과)", "basic": 3000, "required": 21000, "elective": 54000, "total": 78000, "freeElective": 21000, "note": "문학문화콘텐츠·AI응용·융합보안·미래모빌리티학과 단일전공"}'::jsonb),
('MICRO_DEGREE','{"label": "Micro Degree", "credits": 9, "creditMilli": 9000, "note": "유형1은 전공 이수학점 범위 안, 유형2(현장심화형)는 2개 트랙 외 추가 이수"}'::jsonb),
('COMBINATIONS','{"FUSION_I_PLUS_MINOR": 99000, "FUSION_I_PLUS_MICRO_DEGREE": 87000, "FUSION_I_PLUS_THIRD_TRACK": 117000}'::jsonb),
('pre2016','{"FUSION_I": "39+39학점", "FUSION_II": "57+21학점", "DEEP": "78학점", "note": "16학번 이전(학부·학과제에서 트랙제로 전환한 학생 포함) 기준. 세부 기초/필수/선택 배분은 6218 페이지 표 기준 재확인 필요"}'::jsonb);
insert into public.ref_procedures (id,type,term,title,published_at,apply_start,apply_end,result_at,eligibility,notes,average_gpa,source_url) values
('track-select-2027-1-survey','TRACK_SELECT','2027-1','2026학년도 신입생 트랙선택 가수요조사 시행 안내','2026-06-10','2026-06-17T10:00','2026-07-03T23:59',null,'2026학년도 신입생 중 재학생 (단, 미래플러스대학 신입생 제외)','["2026학번 대상 트랙선택 가수요조사(실제 트랙선택은 2026년 11월 예정)", "창의융합대학 내 창업트랙은 2트랙으로만 선택 가능하며, 선발인원 제한 없음", "AI+X 교육이 강조되는 시점에서 2027학년도 1학기 트랙 선택 시부터 AI융합대학(현 창의융합대학)으로 개편 예정인 학과의 제2트랙 선발 인원 제한을 현행 30%에서 40~50%로 확대하는 방안에 대해 2학기 개강 전까지 검토 및 논의 예정", "조사 불참여 시에는 2026학년도 1학기 성적조회가 불가하오니, 반드시 참여하시기 바랍니다", "이번 가수요 조사는 2학년 진학 시 시행하는 트랙 선택과는 무관한 설문조사이므로 실제 트랙선택에 반영되지 않습니다"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/222872/artclView.do'),
('track-select-2026-2','TRACK_SELECT','2026-2','2026학년도 2학기 트랙선택 안내 (26학번 신입생 대상 아님)','2026-04-30','2026-05-04T10:00','2026-05-22T17:00',null,'가. 2017학년도 이후 신입생 중, 두 개학기(1학년 2학기) 과정을 이수 중인 재학생 (미래플러스대학 재학생 제외) 나. 2016학년도 이전 입학생 중, 2~6학기 재학 중인 학부(과)제 재학생 중 트랙제 선택을 희망하는 학생','["트랙 선택 시 등록금은 1트랙, 2트랙 소속계열 등록금의 50%를 합산하여 책정함", "학적반영: 2026학년도 2학기 수강신청 장바구니 직전에 학적 반영됨", "[컴퓨터공학부] 내 트랙선택 자격요건: 아래 과목을 B0 이상으로 이수해야함", "창의융합대학 내 창업트랙은 2트랙으로만 선택 가능하며, 선발인원 제한 없음", "AI+X 교육이 강조되는 시점에서 2027학년도 1학기 트랙 선택 시부터 AI융합대학으로 개편 예정인 학과의 제2트랙 선발 인원 제한을 현행 30%에서 40~50%로 확대하는 방안에 대해 2학기 개강 전까지 검토 및 논의 예정"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/221936/artclView.do'),
('track-select-2026-1','TRACK_SELECT','2026-1','2026학년도 1학기 트랙선택 안내 (11/3~11/21)','2025-10-31','2025-11-03T10:00','2025-11-21T17:00',null,'가. 2017학년도 이후 신입생 중 두개 학기(1학년 2학기) 과정을 이수 중인 재학생(미래플러스대학 재학생 제외) 나. 2016학년도 이전 입학생 중 2~6학기 재학 중인 학부(과)제 학생으로서 트랙제 선택을 희망하는 학생','["[컴퓨터공학부] 내 트랙선택 자격요건: 아래 과목을 B0 이상으로 이수해야함"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/67139/artclView.do'),
('track-select-2025-2','TRACK_SELECT','2025-2','2025학년도 2학기 트랙선택 신청안내(25학번 신입생 대상 아님)','2025-04-30',null,null,null,null,'["본문이 첨부파일로만 게시되어 세부 내용(기간 외)은 수집되지 않음"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/66367/artclView.do'),
('track-select-2025-1','TRACK_SELECT','2025-1','2025학년도 1학기 트랙선택 신청안내 (11/4~11/22)','2024-10-28','2024-11-04','2024-11-22',null,null,'["본문이 첨부파일로만 게시되어 세부 내용(기간 외)은 수집되지 않음"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/65572/artclView.do'),
('track-select-2024-2','TRACK_SELECT','2024-2','2024학년도 2학기 <트랙선택> 신청안내 (5/27 ~ 5/31)','2024-05-02','2024-05-27','2024-05-31',null,null,'["본문이 첨부파일로만 게시되어 세부 내용(기간 외)은 수집되지 않음"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/64354/artclView.do'),
('track-change-2026-2','TRACK_CHANGE','2026-2','2026학년도 2학기 트랙변경 신청 안내(7.20.~7.24.)','2026-07-13','2026-07-20T10:00','2026-07-24T17:00',null,'트랙제를 선택한 3학기 ~ 7학기 재학생 중 트랙변경을 희망하는 재학생','["반영시기: 2026학년도 2학기 수강신청 장바구니 시행 전 학적반영 됨", "트랙변경으로 인해 기취득한 트랙전공학점은 일반선택학점으로 변경되어 졸업시기가 늦어질 수 있으므로 트랙변경에 신중을 기하여야 함", "제1트랙을 본인 소속이 아닌 타 모집단위로의 변경은 2026학년도 2학기 일반전부(과) 신청을 통해 선발된 학생만 가능함.", "타 단과대학 학생이 2트랙을 창의융합대학 내 학과로 트랙변경 시, - 제1지망(창의융합대학 내 학과), 제2지망을 입력", "창의융합대학 내 학과로 2트랙 변경: 주야별 선발인원보다 신청인원이 많을 경우 총 펑점평균 우수자, 전 학기 수강신청학점 높은자, 선이수교과목이 있는 경우 교과목 성적 우수자 순으로 선발함"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/223374/artclView.do'),
('track-change-2026-1','TRACK_CHANGE','2026-1','2026학년도 1학기 트랙변경 신청 안내(1.19.~1.23.)','2026-01-12','2026-01-19T10:00','2026-01-23T17:00',null,'트랙제를 선택한 3학기 ~ 7학기 재학생 중 트랙변경을 희망하는 재학생','["반영시기: 2026학년도 1학기 수강신청 장바구니 시행 전 학적반영 됨", "트랙변경으로 인해 기취득한 트랙전공학점은 일반선택학점으로 변경되어 졸업시기가 늦어질 수 있으므로 트랙변경에 신중을 기하여야 함", "제1트랙을 본인 소속이 아닌 타 모집단위로의 변경은 2025학년도 1학기 일반전부(과) 신청을 통해 선발된 학생만 가능함.", "타 단과대학 학생이 2트랙을 창의융합대학 내 학과로 트랙변경 시, - 제1지망(창의융합대학 내 학과), 제2지망을 입력", "창의융합대학 내 학과로 2트랙 변경: 주야별 선발인원보다 신청인원이 많을 경우 총 펑점평균 우수자, 전 학기 수강신청학점 높은자, 선이수교과목이 있는 경우 교과목 성적 우수자 순으로 선발함"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/67391/artclView.do'),
('track-change-2025-2','TRACK_CHANGE','2025-2','2025학년도 2학기 트랙변경 신청 안내 (7.21~7.25)','2025-07-15','2025-07-21T10:00','2025-07-25T17:00',null,'트랙제를 선택한 3학기 ~ 7학기 재학생 중 트랙변경을 희망하는 재학생','["반영시기: 2025학년도 2학기 수강신청 장바구니 시행 전 학적반영 됨", "트랙변경으로 인해 기취득한 트랙전공학점은 일반선택학점으로 변경되어 졸업시기가 늦어질 수 있으므로 트랙변경에 신중을 기하여야 함", "제1트랙을 본인 소속이 아닌 타 모집단위로의 변경은 2025학년도 1학기 일반전부(과) 신청을 통해 선발된 학생만 가능함.", "타 단과대학 학생이 2트랙을 창의융합대학 내 학과로 트랙변경 시, - 제1지망(창의융합대학 내 학과), 제2지망을 입력", "창의융합대학 내 학과로 2트랙 변경: 주야별 선발인원보다 신청인원이 많을 경우 총 펑점평균 우수자, 전 학기 수강신청학점 높은자, 선이수교과목이 있는 경우 교과목 성적 우수자 순으로 선발함"]'::jsonb,null,'https://www.hansung.ac.kr/bbs/hansung/2127/66640/artclView.do'),
