insert into public.ref_program_graduation (program_id,found,kinds,summary,confidence,detail,collected_at) values
('english-literature-culture',true,'{CERTIFICATE,OTHER,PORTFOLIO}','글로벌캠프 참가와 토익 요건을 모두 충족. 캠프는 글로벌 문화언어 현장학습(1학기)·글로벌 자기주도 문화체험(2학기) 중 1개. 토익은 900점 이상, 또는 학번별 800점 이상 기준(아래 학번별 규정), 또는 4대보험 취업생 특례 중 1개. OPIc·TOEIC Speaking(IH/150점 이상)으로 대체 가능.','MEDIUM','{"options": ["토익 900점 이상(유효기간 내)", "토익 800점 이상 + 학번별 추가조건", "4대보험 가입 취업생: 공인·모의토익 성적표 3장 + 재직·보험 증명"], "minOptions": 1, "cohortRules": [{"cohorts": "23학번까지", "summary": "토익 800점 이상 1회(유효기간 내) 포함 공인토익 3회 응시 성적표 3장 제출."}, {"cohorts": "24학번부터", "summary": "토익 800점 이상(유효기간 내) + 포트폴리오(프로젝트 합 5점: 개인 5·2~3인 3·4인 이상 2점, 영문 자기소개서 첨부, 10분 발표 형식) 제출. 포트폴리오 마감 매년 5월·11월 첫째 주 월요일."}], "substitutes": ["OPIc Intermediate High 이상", "TOEIC Speaking 150점(IH) 이상"], "submission": "졸업서류는 매 학기 종강 2주 전~종강일 원본 제출(2026-1: 6/1~6/22, 진리관 402호 영어영문학부).", "sources": [{"title": "졸업 요건", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1996/218018/artclView.do", "date": "2024-03-05"}, {"title": "졸업요건", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1980/218024/artclView.do", "date": "2022-03-11"}, {"title": "졸업요건", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1982/218021/artclView.do", "date": "2022-03-11"}], "attachmentOnly": [], "note": "트랙 게시판 공지가 영미문화콘텐츠·영미언어정보 트랙 졸업요건을 따르도록 안내. 트랙소개의 예전 문구(문화체험+토익 900)보다 게시판 공지를 우선."}'::jsonb,'2026-10-26'),
('english-language-information',true,'{CERTIFICATE,OTHER,PORTFOLIO}','글로벌캠프 참가와 토익 요건을 모두 충족. 캠프는 글로벌 문화언어 현장학습(1학기)·글로벌 자기주도 문화체험(2학기) 중 1개. 토익은 900점 이상, 또는 학번별 800점 이상 기준(아래 학번별 규정), 또는 4대보험 취업생 특례 중 1개. OPIc·TOEIC Speaking(IH/150점 이상)으로 대체 가능.','HIGH','{"options": ["토익 900점 이상(유효기간 내)", "토익 800점 이상 + 학번별 추가조건", "4대보험 가입 취업생: 공인·모의토익 성적표 3장 + 재직·보험 증명"], "minOptions": 1, "cohortRules": [{"cohorts": "23학번까지", "summary": "토익 800점 이상 1회(유효기간 내) 포함 공인토익 3회 응시 성적표 3장 제출."}, {"cohorts": "24학번부터", "summary": "토익 800점 이상(유효기간 내) + 포트폴리오(프로젝트 합 5점: 개인 5·2~3인 3·4인 이상 2점, 영문 자기소개서 첨부, 10분 발표 형식) 제출. 포트폴리오 마감 매년 5월·11월 첫째 주 월요일."}], "substitutes": ["OPIc Intermediate High 이상", "TOEIC Speaking 150점(IH) 이상"], "submission": "졸업서류는 매 학기 종강 2주 전~종강일 원본 제출(2026-1: 6/1~6/22, 진리관 402호 영어영문학부).", "sources": [{"title": "졸업요건", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1982/218021/artclView.do", "date": "2022-03-11"}], "attachmentOnly": [], "note": "게시물 작성일은 2022-03-11이지만 본문에 2026-1 제출기간이 반영돼 있어 갱신된 것으로 판단."}'::jsonb,'2026-10-26'),
('literature-culture-content-track',true,'{POINTS,PORTFOLIO,EXAM,PAPER}','역량점수제: 4년간(1학년 포함) 필수 3점을 포함해 역량점수 20점 이상 취득. 항목은 지도교수 상담, 문화자원 콘텐츠화 프로젝트, 봉사, 학내외 활동, 자격증, 공모전, 직무수행능력 검증(필수 3점) 등. 1트랙·2트랙 모두 적용.','HIGH','{"options": ["문화콘텐츠 포트폴리오", "졸업시험(국어영역형)", "졸업논문"], "minOptions": 1, "cohortRules": [{"cohorts": "17·18학번", "summary": "지도교수 상담 점수를 학기당 2점(2회 이상 상담)까지 인정(경과조치)."}], "substitutes": [], "submission": "", "sources": [{"title": "[문학문화콘텐츠트랙 / 국어국문전공] 졸업요건 안내", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1985/27975/artclView.do", "date": "2022-02-17"}, {"title": "문학문화콘텐츠트랙 졸업요건", "url": "https://www.hansung.ac.kr/HmnArt/5596/subview.do", "date": null}], "attachmentOnly": [], "note": "options는 필수 항목 ''직무수행능력 검증(5점 중 3점 필수)''에서 고르는 방식. 국어국문전공/한국어문학부(구 학과명)는 필수점수 없이 20점 이상(별도 항목표). 점검표는 HWP 첨부."}'::jsonb,'2026-10-26'),
('korean-language-education',true,'{POINTS}','항목별 점수를 모아 인정받는 방식으로 보임(교육프로그램 참여 점수, 지도교수가 부여하는 한국어교육 콘텐츠 개발 점수 등). 졸업예정 학기 공지 기간에 증빙을 압축해 학과 메일로 제출.','LOW','{"options": [], "minOptions": null, "cohortRules": [], "substitutes": [], "submission": "매 학기 졸업예정자 서류 제출 공지(2026-1: 6/2~6/21 24시) 학과 메일로 압축파일 제출, 제목·파일명 양식 준수.", "sources": [{"title": "2025학년도 후기(2026.08) 졸업예정자 서류 제출 안내", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1981/222776/artclView.do", "date": "2026-06-08"}, {"title": "졸업요건 안내(25.4.23 수정)", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1981/218026/artclView.do", "date": "2024-12-04"}], "attachmentOnly": [], "note": "필요 총점·항목표 원문은 수집되지 않음(게시판 공지는 제출 방법과 점수 인정 시 유의사항만 포함). 한국어교원 2급 자격은 졸업요건이 아니라 졸업 후 개별 신청."}'::jsonb,'2026-10-26'),
('knowledge-information-culture',true,'{EXAM,CERTIFICATE,POINTS}','졸업시험 합격이 졸업요건. 지식정보문화트랙 출제과목 중 3과목 선택 응시, 100점 만점 70점 이상 합격(미통과 시 수료). 1학기 1·2차, 2학기 3차 실시하며 1차 미응시자는 2·3차 응시 불가. 1·2트랙이 디지털인문정보학트랙와 함께면 두 트랙 과목 중 4과목 응시.','HIGH','{"options": [], "minOptions": null, "cohortRules": [{"cohorts": "2022년 8월 졸업생부터", "summary": "현행 졸업시험 내규 적용(2025.3.24 개정: 70점 합격선, 1차 응시 필수, 재학 중 취득 자격증만 인정)."}], "substitutes": ["졸업시험 대체 자격증(재학 중 취득, 1개당 1과목, 최대 4과목; 토익 850+는 2과목)", "전공 비교과포인트(총 950p 이상 시 1과목, 1,100p 이상 시 2과목)"], "submission": "졸업시험 신청은 매년 1학기(2026: 4/24~5/1) 학과 이메일로 신청서 제출, 1차 시험 5월 말. 자격증·비교과 대체 증빙은 졸업학기 종강일까지.", "sources": [{"title": "2026학년도 문헌정보전공 졸업시험 신청 안내 (0430수정)", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1988/221749/artclView.do", "date": "2026-04-23"}, {"title": "[★중요] 문헌정보전공 졸업요건 개정 안내", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1988/28335/artclView.do", "date": "2025-03-24"}, {"title": "지식정보문화트랙 트랙졸업요건", "url": "https://www.hansung.ac.kr/HmnArt/5618/subview.do", "date": null}], "attachmentOnly": [], "note": "문헌정보전공(지식정보문화·디지털인문정보학) 공통 내규. 트랙 페이지는 비교과 대체 최대 1과목으로 적었으나 2025·2026 공지 FAQ는 300p로 2과목 대체 가능하다고 안내."}'::jsonb,'2026-10-26'),
('glocal-history',true,'{WORK,PAPER}','졸업작품(졸업논문 또는 콘텐츠)을 제출하고 지도교수 승인을 받아야 졸업 가능. 영상콘텐츠는 콘텐츠 기획서 필수, 공동제작은 대표 1명이 참여자 전원 기재해 제출. 수업에서 제작한 콘텐츠 제출 시 지도교수 면담 생략 가능.','MEDIUM','{"options": ["졸업논문", "졸업 콘텐츠(+기획서)"], "minOptions": 1, "cohortRules": [], "substitutes": [], "submission": "매 학기 졸업작품 제출 기간 공지(2026-1: 6/15~6/26) 역사트랙 이메일로 제출, 정해진 메일 제목·파일명 양식 준수.", "sources": [{"title": "★2026학년도 1학기 졸업작품 제출 안내★", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1986/222934/artclView.do", "date": "2026-06-12"}], "attachmentOnly": [], "note": "역사 계열 4개 트랙 공동 공지(크리에이티브인문예술대학 교학팀). 미제출 시 졸업·졸업유예 불가. 첨부 HWP는 논문·콘텐츠 표지 양식."}'::jsonb,'2026-10-26'),
('digital-humanities-informatics',true,'{EXAM,CERTIFICATE,POINTS}','졸업시험 합격이 졸업요건. 디지털인문정보학트랙 출제과목 중 3과목 선택 응시, 100점 만점 70점 이상 합격(미통과 시 수료). 1학기 1·2차, 2학기 3차 실시하며 1차 미응시자는 2·3차 응시 불가. 1·2트랙이 지식정보문화트랙와 함께면 두 트랙 과목 중 4과목 응시.','HIGH','{"options": [], "minOptions": null, "cohortRules": [{"cohorts": "2022년 8월 졸업생부터", "summary": "현행 졸업시험 내규 적용(2025.3.24 개정: 70점 합격선, 1차 응시 필수, 재학 중 취득 자격증만 인정)."}], "substitutes": ["졸업시험 대체 자격증(재학 중 취득, 1개당 1과목, 최대 4과목; 토익 850+는 2과목)", "전공 비교과포인트(총 950p 이상 시 1과목, 1,100p 이상 시 2과목)", "웹콘텐츠 출판(트랙 교수 승인 시 2과목 대체)"], "submission": "졸업시험 신청은 매년 1학기(2026: 4/24~5/1) 학과 이메일로 신청서 제출, 1차 시험 5월 말. 자격증·비교과 대체 증빙은 졸업학기 종강일까지.", "sources": [{"title": "2026학년도 문헌정보전공 졸업시험 신청 안내 (0430 수정)", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1989/221748/artclView.do", "date": "2026-04-23"}, {"title": "[★중요] 문헌정보전공 졸업요건 개정 안내", "url": "https://www.hansung.ac.kr/bbs/HmnArt/1989/28576/artclView.do", "date": "2025-03-24"}, {"title": "디지털인문정보학트랙 트랙졸업요건", "url": "https://www.hansung.ac.kr/HmnArt/5625/subview.do", "date": null}], "attachmentOnly": [], "note": "문헌정보전공(지식정보문화·디지털인문정보학) 공통 내규. 트랙 페이지는 비교과 대체 최대 1과목으로 적었으나 2025·2026 공지 FAQ는 300p로 2과목 대체 가능하다고 안내."}'::jsonb,'2026-10-26'),
